def _gen_logits(self, model, x, plen):
    """Logits aligned so column j predicts generated position plen+j."""
    out = model(x)
    logits = out.logits if hasattr(out, "logits") else \
        (out[0] if isinstance(out, (tuple, list)) else out)
    if self._shift:
        return logits[:, plen - 1:-1, :]
    return logits[:, plen:, :]

